rows=json.loads((D/'inventory.json').read_text())
rows=[{k:x[k] for k in ['url','famille','plateforme','title','h1','http_status','canonical','lastmod_sitemap','etat_base_tube','equivalent_ou_route_proposee','priorite_proposee','donnees_necessaires','schema_types']} for x in rows]
page='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kabo → Base.tube · 500 pages cartographiées</title><style>
:root{font-family:system-ui,-apple-system,sans-serif;color:#18201d;background:#f4f5f0;--accent:#e66027}*{box-sizing:border-box}body{margin:0}header,main{max-width:1320px;margin:auto;padding:32px}header{padding-top:48px}.eyebrow{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:#53605a}h1{font-size:clamp(30px,4vw,52px);letter-spacing:-.045em;margin:16px 0}h2{font-size:24px;letter-spacing:-.025em}p{line-height:1.6;max-width:960px}.lead{font-size:19px;color:#48564e}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat,.panel{background:white;border:1px solid #dce1d9;border-radius:12px;padding:22px}.stat strong{font-size:34px;display:block}.stat span{color:#637267;font-size:14px}.panel{margin-top:20px}.bar{height:18px;display:flex;border-radius:9px;overflow:hidden;margin:20px 0}.legend{display:flex;flex-wrap:wrap;gap:15px;font-size:13px}.legend b{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px}.priorities{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.priority{border-left:3px solid var(--accent);padding-left:16px}.priority strong{display:block}.priority p{font-size:14px;margin-bottom:0}.filters{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}input,select{font:inherit;border:1px solid #ccd4c9;border-radius:7px;padding:11px;background:white;min-width:130px}input{flex:1;min-width:220px}a{color:#a53f15;text-decoration:none}a:hover{text-decoration:underline}button{cursor:pointer;font:inherit;border:1px solid #ccd4c9;background:#fff;border-radius:7px;padding:10px}#summary{font-size:13px;color:#526258}.tablewrap{overflow:auto;max-height:640px;border:1px solid #dce1d9;border-radius:8px}table{border-collapse:collapse;width:100%;font-size:13px}th{position:sticky;top:0;background:#eaf0e6;text-align:left;z-index:1}th,td{padding:13px;border-bottom:1px solid #e5e9e1;vertical-align:top}td:first-child{min-width:270px;max-width:450px}td:nth-child(4){min-width:200px}small{display:block;color:#6b776f;margin-top:5px;overflow-wrap:anywhere}.badge{background:#f1f3eb;border-radius:4px;display:inline-block;padding:4px 6px;white-space:nowrap}details{margin-top:9px}summary{cursor:pointer;color:#8b461e}footer{color:#66716a;font-size:12px;padding:30px 0}.links{display:flex;flex-wrap:wrap;gap:16px;margin:20px 0}@media(max-width:750px){header,main{padding:20px}.stats{grid-template-columns:repeat(2,1fr)}.priorities{grid-template-columns:1fr}.stat{padding:16px}h1{line-height:1.08}} 
</style></head><body><header><div class="eyebrow">Recherche concurrentielle · 3 octobre 2026 · Base.tube</div><h1>Kabo : le corpus derrière le SEO.</h1><p class="lead">500 URL vérifiées. Une même base de créateurs et de vidéos sert aux profils, classements, tendances et outils. L’opportunité Base.tube : y ajouter une lecture utile du packaging, puis relier chaque exemple à l’audit et à Studio.</p><div class="stats"><div class="stat"><strong>500</strong><span>URL Kabo · toutes HTTP 200</span></div><div class="stat"><strong>373</strong><span>Profils + classements + tendances</span></div><div class="stat"><strong>69</strong><span>Outils · 3 équivalents Base.tube</span></div><div class="stat"><strong>27</strong><span>URL du sitemap Base.tube · 12 articles</span></div></div><div class="links"><a href="analyse.md">Lire le rapport complet ↗</a><a href="inventaire-kabo-500.csv" download>Inventaire CSV · 500 URL ↓</a><a href="outils-69.csv" download>69 outils ↓</a><a href="guides-38.csv" download>38 guides ↓</a><a href="inventaire-base-27.csv" download>Base.tube ↓</a></div></header><main><section class="panel"><h2>74,6 % des URL sont des pages de données</h2><div class="bar"><span style="width:44.4%;background:#e66027"></span><span style="width:28.6%;background:#efab57"></span><span style="width:13.8%;background:#506d53"></span><span style="width:7.6%;background:#95ad80"></span><span style="width:1.6%;background:#334e68"></span><span style="width:4%;background:#cbd3c6"></span></div><div class="legend"><span><b style="background:#e66027"></b>222 profils</span><span><b style="background:#efab57"></b>143 classements</span><span><b style="background:#506d53"></b>69 outils</span><span><b style="background:#95ad80"></b>38 guides</span><span><b style="background:#334e68"></b>8 tendances</span><span><b style="background:#cbd3c6"></b>20 hubs et autres</span></div><p>Profils : 106 YouTube, 63 Instagram, 53 TikTok. Classements : 137 YouTube, dont 77 pays, et 6 autres listes. Ces comptes sont ceux du sitemap ; le corpus de données annoncé par Kabo est plus vaste.</p></section><section class="panel"><h2>Les trois priorités Base.tube</h2><div class="priorities"><div class="priority"><strong>1. Une bibliothèque d’analyses</strong><p>20 chaînes pilotes : vrais exemples, données datées, observations de titres et thumbnails, hypothèses et expériences.</p></div><div class="priority"><strong>2. Publier le socle existant</strong><p>6 galeries originales dans /thumbnails. Le moteur existe dans le code ; zéro page est publiée et Fortnite reste un draft.</p></div><div class="priority"><strong>3. Relier recherche et action</strong><p>Outliers par niche, guides, puis audit et génération. Préserver la chaîne sélectionnée au passage vers l’application.</p></div></div><p><strong>Test Monid/TikHub :</strong> handle MKBHD résolu, profil et première page de vidéos obtenus. 3 appels réussis, coût facturé : 0,0045 $. Compteurs arrondis et dates relatives exigent normalisation et qualification. Captions, Instagram et TikTok n’ont pas été testés.</p></section><section class="panel"><h2>Explorer les 500 pages</h2><p>Équivalence = couverture dans le sitemap public audité. Priorités et nouvelles routes = propositions. Les outils Kabo ont été lus, pas exécutés.</p><div class="filters"><input id="q" aria-label="Rechercher dans l’inventaire" placeholder="Chercher un sujet, créateur ou outil…"><select id="family" aria-label="Famille"><option value="">Toutes les familles</option></select><select id="platform" aria-label="Plateforme"><option value="">Toutes les plateformes</option></select><select id="priority" aria-label="Priorité"><option value="">Toutes les priorités</option></select><button id="reset">Réinitialiser</button></div><p id="summary" aria-live="polite"></p><div class="tablewrap"><table><thead><tr><th>Page et URL Kabo</th><th>Famille</th><th>Priorité</th><th>Couverture Base.tube</th><th>Route / données</th></tr></thead><tbody id="rows"></tbody></table></div></section><footer>Sources : <a href="https://kabo.sh/sitemap.xml" target="_blank" rel="noopener">sitemap Kabo</a> et <a href="https://base.tube/sitemap.xml" target="_blank" rel="noopener">sitemap Base.tube</a>, lecture des 527 pages, code local et trois appels Monid. HTTP 200 et meta indexable ne prouvent pas l’indexation Google. Trafic, positions et conversions Kabo inconnus. Hypothèse : « AI Channel » désigne l’audit YouTube Base.tube.</footer></main><script>
const DATA=__DATA__;
const q=document.getElementById('q'),fam=document.getElementById('family'),plat=document.getElementById('platform'),pri=document.getElementById('priority'),tbody=document.getElementById('rows');
for(const [el,key] of [[fam,'famille'],[plat,'plateforme'],[pri,'priorite_proposee']]){for(const v of [...new Set(DATA.map(x=>x[key]))].sort()){const o=document.createElement('option');o.value=v;o.textContent=v;el.append(o)}}
const norm=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function cell(text){const td=document.createElement('td');td.textContent=text;return td}
function render(){const needle=norm(q.value.trim());const filtered=DATA.filter(x=>(!fam.value||x.famille===fam.value)&&(!plat.value||x.plateforme===plat.value)&&(!pri.value||x.priorite_proposee===pri.value)&&(!needle||norm(Object.values(x).join(' ')).includes(needle)));tbody.replaceChildren();const fragment=document.createDocumentFragment();for(const x of filtered){const tr=document.createElement('tr');const first=cell(''),a=document.createElement('a');a.href=x.url;a.target='_blank';a.rel='noopener';a.textContent=x.title;first.append(a);const sm=document.createElement('small');sm.textContent=x.url.replace('https://kabo.sh','');first.append(sm);const details=document.createElement('details'),sum=document.createElement('summary');sum.textContent='Preuves SEO';details.append(sum);const txt=document.createElement('small');txt.textContent='H1 : '+x.h1+' | HTTP '+x.http_status+' | lastmod '+x.lastmod_sitemap+' | canonical '+x.canonical+' | JSON-LD : '+x.schema_types;details.append(txt);first.append(details);tr.append(first,cell(x.famille+' · '+x.plateforme),cell(x.priorite_proposee),cell(x.etat_base_tube));const last=cell(x.equivalent_ou_route_proposee||'—'),small=document.createElement('small');small.textContent=x.donnees_necessaires;last.append(small);tr.append(last);fragment.append(tr)}tbody.append(fragment);document.getElementById('summary').textContent=filtered.length+' / 500 pages affichées';}
for(const el of [q,fam,plat,pri])el.addEventListener(el===q?'input':'change',render);document.getElementById('reset').addEventListener('click',()=>{q.value='';fam.value='';plat.value='';pri.value='';render()});render();
</script></body></html>'''
